theorem pi_le_norm_Gamma_half_mul {M : ℝ}
    (hM : ∀ x ∈ Set.Icc (1 / 2 : ℝ) 1, Real.Gamma x ≤ M) {ρ : ℂ}
    (h0 : 0 < ρ.re) (h1 : ρ.re < 1) :
    Real.pi ≤ ‖Complex.Gamma (ρ / 2)‖ * M * Real.exp (Real.pi * |ρ.im| / 2)

